script_dir=fileparts(mfilename('fullpath'));root_dir=fileparts(script_dir);w=fullfile(root_dir,'waveforms','13-speed-pi');a=fullfile(root_dir,'assets','13-speed-pi');if ~exist(a,'dir');mkdir(a);end
step=readtable(fullfile(w,'plecs_speed_step_aw.csv'),'VariableNamingRule','preserve');load=readtable(fullfile(w,'plecs_load_step_aw.csv'),'VariableNamingRule','preserve');aw=readtable(fullfile(w,'plecs_recovery_aw.csv'),'VariableNamingRule','preserve');noaw=readtable(fullfile(w,'plecs_recovery_no_aw.csv'),'VariableNamingRule','preserve');s=readtable(fullfile(w,'plecs_speed_pi_summary.csv'),'VariableNamingRule','preserve');
