nexttile;plot(step.time_s,step.speed_target_rad_s,'--','LineWidth',1.2);hold on;plot(step.time_s,step.speed_rad_s,'LineWidth',1.3);plot(load.time_s,load.speed_rad_s,'LineWidth',1.2);ylabel('speed / rad/s');grid on;legend('target','speed step','load step','Location','eastoutside');
